import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed, collectProgressTelemetry } from './src/workspace.js';
const pending = new Map();
const feed = createProgressFeed({ initialPacket: 'warm', decode: packet => packet.startsWith('async') ? new Promise(resolve => pending.set(packet, resolve)) : packet });
const history = [], shown = [], queue = [], deltas = [];
const ws = createTransferWorkspace({ transport() {}, onCancel() {}, record: x => queue.push(x), showQueued() {}, recordProgress: x => history.push(x), showProgress: x => shown.push(x) });
const file = { id: 'f', progressFeed: feed };
const stopTelemetry = collectProgressTelemetry(feed, x => deltas.push(x));
ws.select(file);
assert.deepEqual(shown.map(x => x.frame), ['warm']);
assert.deepEqual(deltas, []);
feed.emit('async-old'); feed.emit('new'); pending.get('async-old')('old');
await Promise.resolve();
assert.deepEqual(shown.map(x => x.frame), ['warm', 'new']);
assert.deepEqual(history.map(x => x.frame), ['warm', 'new', 'old']);
feed.emit('async-retry-old'); ws.retry(); pending.get('async-retry-old')('retry-old');
await Promise.resolve();
assert.equal(shown.at(-1).frame, 'warm');
assert.equal(shown.filter(x => x.frame === 'retry-old').length, 0);
ws.hide(); ws.select(file); assert.equal(shown.at(-1).frame, 'warm');
stopTelemetry(); ws.dispose();
assert.deepEqual(queue.map(x => x.kind), ['select', 'retry', 'select']);
console.log('targeted progress scenarios passed');
EOF"

